INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(343000, 0, 3430, 0, 0, 0, 'Eversong Woods', 'Eversong Woods is the northern heart of Quel''Thalas, a forest of golden leaves that the magisters of old bound in a perpetual spring. Silvermoon City rises in its northeast, and Sunstrider Isle lies just off its northern shore. The land still bears the wound of the Third War. When Arthas led the Scourge to the Sunwell, his army tore a blighted road through the forest and into the capital itself, and that black furrow, the Dead Scar, still draws the undead north from the Ghostlands. With the Sunwell lost, the survivors took the name blood elves and learned to sate their hunger for magic from other sources. Those who cannot master that hunger become the Wretched, who raid roads and ruins for any scrap of power. Arcane sanctums now draw energy from the ley lines, the Farstriders hold the Amani trolls at bay in the southeast, and many elves still speak of finding their true fate in Outland.', 'warcraft.wiki.gg/wiki/Eversong_Woods (perpetual springtime, Dead Scar, Wretched, sanctums, Amani); page_text 2823-2827 (Saga of the Sin''dorei: Sunwell, Arthas, renamed blood elves); npc_text 8534 (sanctums siphon ley-line power); quest 8476 description (Amani raids); quest 9255 reward text (true fate in Outland); warcraft.wiki.gg/wiki/Dead_Scar'),
(343001, 1, 3430, 1, 0, 0, 'Sunstrider Isle', 'Sunstrider Isle, off the northern shore of Eversong, was once a tranquil place of study, its creatures bound to calm by the spells of the magisters. When the Scourge destroyed the Sunwell, that control shattered. Mana wyrms set to guard the floating Burning Crystals now roam errant, lynxes have been warped by the crystals'' unchecked power, and the tenders that once kept the gardens attack on sight. From the Sunspire, the great tower of the isle, Magistrix Erona and her fellow teachers instruct a new generation, while Well Watcher Solanian keeps his vigil over the Sunwell, or what remains of it. A bridge to the south carries the outrunners'' road to the mainland.', 'quest 8325, 8326, 8334 descriptions; quest 8336 description and request text (tranquil place of study; creatures bound into complacency until the Sunwell fell); quest 8330 request text (vigil over the Sunwell, or what remains of it); quest 8347 description (bridge leading south); npc_text 16703 (Erona); warcraft.wiki.gg/wiki/Sunstrider_Isle; subzone list: 3484 The Sunspire'),
(343002, 1, 3430, 2, 0, 0, 'Falthrien Academy', 'West of the Sunspire floats Falthrien Academy, a great building crowned with ornate spires that once served the scholars of the isle. It has fallen to Felendren the Banished, a former student who ignored the warnings of his teachers and gave himself over to his craving for magic until he became one of the Wretched. Exiled from elven lands, he has made his lair atop the academy, served by arcane wraiths. Some of those wraiths carry dark, tainted slivers of crystallized mana, and the arcanists of the Sunspire suspect such slivers may help reveal the strange corruption that grips the isle.', 'quest 8327 reward text (huge floating building with ornate spires, to the west); quest 8335 description; quest 8338 description and reward text; warcraft.wiki.gg/wiki/Felendren_the_Banished; DB spawn: Felendren 15367'),
(343003, 1, 3430, 3, 0, 0, 'Shrine of Dath''Remar', 'On the western side of Sunstrider Isle stands a shrine to Dath''Remar Sunstrider, first king of the high elves. Ages ago he led the exiled Highborne away from Kalimdor and through the storms of the Maelstrom in search of a new homeland, and the name Sunstrider, he who walks the day, began with him. A bronze placard on the shrine calls him a noble elf and declares that all who prosper in Quel''Thalas do so thanks to him. Well Watcher Solanian urges every newcomer to read it. Lately visitors feel an uneasy pulse of the same strange power that has gripped the rest of the isle.', 'quest 8345 description and reward text; page_text 2936 (placard text and the strange power); page_text 1847, 1854 (Highborne exile, Maelstrom, Sunstrider means he who walks the day); gameobject 180516 Shrine of Dath''Remar'),
(343004, 1, 3430, 4, 0, 0, 'Ruins of Silvermoon', 'The western half of Silvermoon City never recovered from the day the Scourge broke through it on the march to the Sunwell. Its lanes and halls stand empty and cracked, and they have become a haunt of the Wretched, who will kill for a handful of mana crystals. Even Dawning Lane, the safest road through, is no guarantee: the outrunners who run goods from Sunstrider Isle found their latest courier dead there, the third lost this month. Arcane patrollers built by earlier generations to guard the city still walk their rounds, calling on all to uphold the law, but they no longer recognize the elves as their masters. The Wretched ringleader Thaelis the Hungerer hides in the Commons Hall.', 'warcraft.wiki.gg/wiki/Ruins_of_Silvermoon (western half, Dead Scar, Wretched); quest 9704 description and 9705 reward text (third outrunner this month); quest 8472 description (patrollers crafted by our forefathers, attack on sight); creature_text 15638 (Uphold the law); warcraft.wiki.gg/wiki/Thaelis_the_Hungerer (Commons Hall); subzone list: 3532 Dawning Lane, 3531 Skulking Row, 3534 Feth''s Way, 3662 Commons Hall; quest 8350 description (safety of Dawning Lane); DB spawns: Slain Outrunner 17849 in 3532; Thaelis 15949 terrain area 3533'),
(343005, 1, 3430, 5, 0, 0, 'Falconwing Square', 'Falconwing Square sits in the southeastern corner of the Ruins of Silvermoon, at the end of Dawning Lane, the one corner of the ruined district where order has been restored. Its inn is the first stop on the mainland for the graduates of Sunstrider Isle, and trainers of many crafts and callings teach nearby. Aeldon Sunbrand, captain of the Blood Hawks, directs the struggle against the Wretched from here, and Magister Jaronis gathers the arcane cores of broken patrollers to make up for sanctums running below full strength. In the square Sergeant Kan''ren questions a captured Wretched, whose kind have killed two of his men this month, and a posted bounty names Thaelis the Hungerer.', 'warcraft.wiki.gg/wiki/Falconwing_Square; quest 8350 (Erona''s package to the inn); quest 8472 description and reward text; npc_text 8229 (Sunbrand); npc_text 8698 and creature_text 16924 (Kan''ren); gameobject 180918 Wanted: Thaelis the Hungerer; creature_template 15403 subname Captain of the Blood Hawks; quest 8472 reward text (sanctums not at full capacity); warcraft.wiki.gg/wiki/Falconwing_Square (southeastern corner, end of Dawning Lane)'),
(343006, 1, 3430, 6, 0, 0, 'North Sanctum', 'Southwest of Falconwing Square stands the North Sanctum, one of the arcane sanctums that now sustain Quel''Thalas. Currents of ley energy, invisible to the naked eye, run beneath the land, and the sanctums siphon power from them as a steady replacement for the lost Sunwell. Ley-Keeper Caidanis oversees its upkeep. Of late he has also played host to Prospector Anvilward, a dwarven envoy from Ironforge, and has remarked that the guest''s enthusiastic interest in the sanctums'' operations is most unexpected.', 'quest 8895 description (southwest of Falconwing Square); npc_text 8534 (ley-line currents invisible to the naked eye; steady source of energy); creature_text 15405, 15420; quest 8482 reward text (envoy from Ironforge); warcraft.wiki.gg/wiki/North_Sanctum'),
(343007, 1, 3430, 7, 0, 0, 'West Sanctum', 'The West Sanctum, southwest of the North Sanctum, is one of the primary sources of arcane power in the region, and it is badly broken. Ley-Keeper Velania warned against raising the load it carried, and when one of its energy converters was destroyed, manawraiths and mana stalkers came pouring out of the structure. The accident set rumors of Darnassian sabotage running through Eversong, and night elf scouts have indeed been found skulking nearby. The papers one of them carried told a stranger story: maps of strategic buildings across Eversong, a sketch of a sanctum, and notes written in Dwarvish.', 'quest 9119 description (southwest of the North Sanctum); quest 8486 description; quest 9352 description and reward text (primary energy source, Darnassian rumors); quest 8482 description and reward text; DB spawns: Darnassian Scout 15968 x5 near Ley-Keeper Velania 15401'),
(343008, 1, 3430, 8, 0, 0, 'Tranquil Shore and Golden Strand', 'Along the western coast of Eversong, the Tranquil Shore and the Golden Strand have been overrun by Grimscale murlocs. From a bluff above the shore, the Farstrider Hathvelion Sungaze has vowed to drive them back to the murky depths, though no amount of slaughter has yet sent them into retreat. Their self-styled chieftain, Mmmrrrggglll, wanders the strand south of the river inlet, flaunting the ring of a friend of Hathvelion''s whom he slew. The Grimscale are bold raiders too: from their huts near Sunsail Anchorage they carried off a merchant captain''s cargo and even her navigation rutters.', 'quest 8884 description, request and reward text; quest 8885 description and reward text; quest 8886 description (huts west and south of the anchorage on the Golden Strand); quest 8887; DB spawns: Hathvelion 15920, Mmmrrrggglll 15937'),
(343009, 1, 3430, 9, 0, 0, 'Sunsail Anchorage', 'Sunsail Anchorage, west of Fairbreeze Village, is the shipyard of Eversong, and some of its vessels date back to the Second War. The elves had reclaimed it once, but a bold attack by the Wretched drove them out again and left the yard in the hands of thugs and hooligans led by Aldaron the Reckless, who holds the top floor of the building beside the anchorage. The defenders retreated so hastily that most of their weapons were left behind. Velendris Whitemorn and his rangers now hold a guarded camp just to the east, where the merchant Captain Kelisendra waits for the chance to repair her ship and sail again.', 'warcraft.wiki.gg/wiki/Sunsail_Anchorage (ships from the Second War, reclaimed then lost to Aldaron); quest 8892 description (west of Fairbreeze); quests 8480, 9076 descriptions; quest 8886 and 8887 reward and request texts; DB spawns: Aldaron the Reckless 16294, Velendris 15404, Kelisendra 15921; CreatureDisplayInfo/Extra.dbc: display 15915 male blood elf'),
(343010, 1, 3430, 10, 0, 0, 'Saltheril''s Haven', 'Down the road west of Fairbreeze Village lies Saltheril''s Haven, the country estate of Lord Saltheril, where the party never seems to end. While rangers bleed on the borders, the lord and his guests toast the magnificence of Quel''Thalas with wine from Silvermoon, springpaw appetizers and fireworks, and his companion Elisara Sunstriker muses about an evening picnic within sight of the fighting. The estate is not wholly idle: teachers of alchemy, enchanting, tailoring and herbalism keep their trades on its grounds. Magistrix Landra Dawnstrider of Fairbreeze considers its master a fool living in denial of the war.', 'quest 9395 description; quest 9067 description; creature_text 16147 (Elisara); DB spawns at area 3468: Arcanist Sheynathren, Magistrix Eredania, Sempstress Ambershine; Botanist Tyniarrel nearby; warcraft.wiki.gg/wiki/Saltheril''s_Haven'),
(343011, 1, 3430, 11, 0, 0, 'Fairbreeze Village', 'Fairbreeze Village is the chief settlement of southern Eversong, led by Magistrix Landra Dawnstrider and still standing, as its people say, as a testament to elven tenacity. It is pressed from two sides, by the Scourge coming up the Dead Scar to the east and by the Wretched of Sunsail Anchorage to the west, and reinforcements from Silvermoon are slow to come. Ranger Sareyn holds the eastern road against the undead, Ranger Degolien has been sent to deal with the Wretched, and the craftsman Velan Brightoak trades armor for springpaw pelts, grumbling that night elf poachers travel all this way to take them.', 'warcraft.wiki.gg/wiki/Fairbreeze_Village (village leader Landra Dawnstrider); npc_text 8535 (Ardeyn: testament to our race''s tenacity); quest 9358 description (Scourge on the east, Wretched to the west); quest 9252 description (no sign of reinforcements); quest 9256 reward text; quest 8491 description (night elf poachers)'),
(343012, 1, 3430, 12, 0, 0, 'The Dead Scar', 'The Dead Scar is the path Arthas carved through Quel''Thalas on his march to the Sunwell, where he meant to raise Kel''Thuzad. Wherever the Scourge passed, the land was blighted, and a long black furrow of dead soil now runs from the Ghostlands across the Elrendar River, through the heart of Eversong and in at the broken gates of Silvermoon City. The taint still draws the undead. Plaguebone pillagers, rotlimb marauders and darkwraiths trudge up the Scar from the south, and rangers such as Jaela spend long days cutting them down within sight of the capital.', 'warcraft.wiki.gg/wiki/Dead_Scar (pre-Cataclysm sections); quest 8475 description; quest 9252 objectives; npc_text 8403 and creature_text 15416 (Ranger Jaela); page_text 2824 (Kel''Thuzad raised with the Sunwell); warcraft.wiki.gg/wiki/Dead_Scar (across the Elrendar River, shattered main gates)'),
(343013, 1, 3430, 13, 0, 0, 'East Sanctum', 'The East Sanctum stood squarely in the way when Arthas drove his army toward Silvermoon, and it has been useless ever since. Its ley energies are disrupted, its soil tainted and its grounds a magnet for the undead. Apprentice Mirveda, pursuing research her former mentor long ago lost faith in, came here to learn whether the damage could be undone. Her samples gave a grim answer: the very nature of the soil has been altered and the taint cannot be reversed. Magistrix Landra Dawnstrider, who reviewed the findings, took them as one more reason for the sin''dorei to seek their true fate in Outland.', 'quest 8487 description; quest 8488 reward text; quest 9254 description and reward text; quest 9255 description and reward text; creature_text 15402'),
(343014, 1, 3430, 14, 0, 0, 'Stillwhisper Pond', 'Southeast of Silvermoon City lies Stillwhisper Pond, where Instructor Antheol delivers his lectures on the elements. He likens students to sheep, likeable enough while watched but apt to fall off a cliff the moment they are left alone, and his own pupils prove the point. When Wretched robbers threw his elemental grimoire into the river, apprentices Meledor and Ralen tried to bribe a passerby into telling him the soaked book had merely been dropped in a puddle. Antheol learned the truth, had the pair struck with his disciplinary rod, which left them briefly transformed, and suspended their apprenticeships until they earn them back.', 'quest 9064 description (southeast of Silvermoon); npc_text 9061 (students are like sheep); quests 9035, 9062, 9066 descriptions and reward texts; creature_text 15941, 15945; warcraft.wiki.gg/wiki/Stillwhisper_Pond'),
(343015, 1, 3430, 15, 0, 0, 'Farstrider Retreat', 'Farstrider Retreat, south of Silvermoon City in eastern Eversong, is a lodge of the Farstriders, rangers sworn to defend their people from enemies near and far. Under Lieutenant Dawnrunner they hold the line against the Amani trolls of Zeb''Watha and Tor''Watha, whose raids come almost daily. Arathel Sunforge works the forge here and, for all the old enmity between the races, admits a craftsman''s admiration for Amani weapons. The lodge has also become a refuge for Magister Duskwither, who abandoned his spire to the north after a disaster he blames on himself. Just to the south, Elrendar Falls spill down from Lake Elrendar.', 'npc_text 8755 (Dawnrunner: rangers sworn to defend our people from enemies both near and far); quest 8476 description; quest 8477 description; quest 9617 description (Farstrider Retreat lies south of Silvermoon); quest 8888 description and 8890 reward text; page_text 2853 (sabbatical at the Farstrider Retreat); warcraft.wiki.gg/wiki/Elrendar_Falls (just south of Farstrider Retreat)'),
(343016, 1, 3430, 16, 0, 0, 'Duskwither Spire', 'North of Farstrider Retreat, where the road branches east, Duskwither Spire floats above its grounds, reached by an orb of translocation in the pavilion below. Magister Duskwither kept a school here until his research into purifying tainted magic turned his own apprentices into Wretched, and he emptied the Spire in haste without shutting down its power. Strange magical creatures, mana serpents and ether fiends among them, now overrun the place, and a rarely seen arcane elemental named Eldinarcus roams the grounds. Groundskeeper Wyllithen, whom nobody remembered to tell to leave, still tries to keep the gardens in order.', 'quest 8888 description (route from the retreat); quest 8891 reward text; page_text 2846-2853 (Duskwither''s journal); quests 8894, 9394; warcraft.wiki.gg/wiki/Duskwither_Spire (orb of translocation in a pavilion beneath); warcraft.wiki.gg/wiki/Eldinarcus (rare, Duskwither Grounds); DB: Eldinarcus 16854 rank 4, 3 spawn points in area 3480'),
(343017, 1, 3430, 17, 0, 0, 'The Scorched Grove', 'In the southwest of Eversong, the westernmost of the runestones that warded the border was destroyed in a Scourge attack. To keep the plague''s taint from spreading, the elves burned the forest around it, a decision their rangers still call one of the hardest of these times. The treants who had long been friends to Quel''Thalas would not accept the loss, and their withered green keepers labor to make the grove grow again, so the elves must now cut down their old allies. Larianna Riverwind watches over the grove from a tower to the northwest, and Old Whitebark, elder of the treants, wanders the ashes.', 'quest 9258 description; quest 8473 description and reward text; npc_text 8504 (Western Runestone failed long ago); quest 10166 description (treant elder); warcraft.wiki.gg/wiki/Scorched_Grove (treants try to nurture life back); DB spawns: Withered Green Keeper 15637 x44, Old Whitebark 15409'),
(343018, 1, 3430, 18, 0, 0, 'Runestones Falithas and Shan''dor', 'Along the southern edge of Eversong stand Runestone Falithas and Runestone Shan''dor, two of the few surviving stones that once raised a protective barrier across the border with the Ghostlands. Many were destroyed in Arthas''s attack and others were stolen. Runewarden Deryan has sworn that while he lives the remaining stones will not fail. Falithas, where he keeps watch, is the only one still at full strength. The stone to its east has gone dark, but it may yet be recharged with an infused crystal, if its defenders can hold off the Scourge drawn to it while the energy takes hold.', 'quest 8490 description and reward text; npc_text 8504 (Deryan''s oath); quest 9253 description; warcraft.wiki.gg/wiki/Runestone_Falithas (only one fully intact and functional); warcraft.wiki.gg/wiki/Runestone_Shan''dor (deactivated, reclaimed with energy from an arcane crystal); DB: Infused Crystal Focus 181164 spawned in area 3914 (Runestone Shan''dor), east of Deryan 16362 in 3913'),
(343019, 1, 3430, 19, 0, 0, 'Zeb''Watha and Tor''Watha', 'In the southeast of Eversong, beyond the Farstrider Retreat, the Amani trolls keep two villages on either side of Lake Elrendar. Tor''Watha is the larger, home to berserkers, axe throwers and the spearcrafter Otembe, whose magical hammer is said to be so light and well balanced that it lets him work with rare skill. Caged there, poisoned and left to die, is Ven''jashi, a Darkspear troll whose village the Amani burned. Across the water at Zeb''Watha rules Chieftain Zul''Marosh, and plans taken from him mark the positions of the Farstrider Retreat and Fairbreeze Village.', 'quest 8476 description; quest 8477 description; quest 8479 description, log text and reward text; quest 9360 description; warcraft.wiki.gg/wiki/Zeb''Watha (much smaller than Tor''Watha, chieftain); DB spawns: Otembe 15408, Ven''jashi 15406, Tregla 16855 (area 3476), Zul''Marosh 15407'),
(343020, 2, 3430, 1, 2, 0, 'Well Watcher Solanian', 'Well Watcher Solanian keeps his post on an upper platform of the Sunspire, which once gave a beautiful view of the Sunwell. Some accuse him of dwelling too much on the past, and he does insist that every visitor to Sunstrider Isle honor the shrine of Dath''Remar. Yet his counsel looks forward. The blood elves, he teaches, are survivors, and each of them must master the endless hunger for magic before it masters them. Young students of the Sunspire are sent up to him once their first lessons are done, and he puts them to work reclaiming the isle.', 'npc_text 7784; quest 8345 description; quest 8330 description and request text; quests 10068-10073 (trainers send students to him); creature_template 15295 faction 1604'),
(343021, 2, 3430, 2, 0, 0, 'Felendren the Banished', 'Felendren was once a pupil on Sunstrider Isle. He refused to heed the warnings of his mentors and elders, never learned to control his craving for magic, and succumbed to it, becoming one of the Wretched, a shell of the elf he had been. Banished from blood elf lands, he now lurks atop Falthrien Academy with arcane wraiths as his servants, a threat to the Sunspire itself. Magister Duskwither recorded his fall in a journal as a spur to redouble his own research, and the teachers of the isle hold him up as a warning that every blood elf shares the same potential fate.', 'quest 8335 description, request and reward texts; page_text 2848 (Duskwither''s journal on Felendren); warcraft.wiki.gg/wiki/Felendren_the_Banished'),
(343022, 2, 3430, 3, 2, 0, 'Aeldon Sunbrand', 'Aeldon Sunbrand, captain of the Blood Hawks, keeps order around Falconwing Square. He regards the Wretched as a constant thorn: when they are not endangering themselves by tapping unstable arcane sources, they are hatching half-baked schemes against respectable society, and he cares less whether they blow themselves up than how it would make his men look. When papers taken from a night elf spy turned out to be written in Dwarvish, it was Sunbrand who named the culprit, the envoy from Ironforge, and ordered him quietly removed. Word went to the ranger general, and he promises the dwarves will pay dearly.', 'npc_text 8229; quest 8463 description; quest 8482 reward text; quest 8483 description and reward text; creature_template 15403 subname Captain of the Blood Hawks, faction 1604'),
(343023, 2, 3430, 4, 0, 0, 'Prospector Anvilward', 'Prospector Anvilward came to Eversong from Ironforge as an envoy, and Ley-Keeper Caidanis has been showing him the workings of the North Sanctum. The dwarf is gruff with strangers, advising them to be on their way if they want no trouble. His curiosity proved more than diplomatic. Notes in Dwarvish, carried by a night elf scout, called the elves'' experiments reckless and revealed that their author had been sent to watch the results of the West Sanctum''s malfunction. Captain Sunbrand read them as Anvilward''s work and ordered his quiet death, for Silvermoon could not let it be known that it had welcomed a spy.', 'npc_text 8239 (gossip); creature_text 15405, 15420; quest 8482 reward text; quest 8483 description; creature_template 15420 faction 35, gossip_menu 21310'),
(343024, 2, 3430, 5, 2, 0, 'Magister Duskwither', 'Magister Duskwither once taught apprentices at Duskwither Spire, hoping to find his people a safe supplement to the lost Sunwell. His research turned to filtering the impurities out of corrupted fel power sources, and an early success drew most of his students into the work. Then his chief apprentice, Telethayon, withered into a Wretched before his eyes, and more followed. Duskwither got the rest away by announcing that he was taking a sabbatical at the Farstrider Retreat, and there he waits, wracked with guilt. He calls his journal the proof of his crime and burns it so that no one can repeat his mistakes.', 'page_text 2846-2853 (journal); quest 8888 description; quest 8890 reward text; quest 8891 reward text; creature_text 15951 (Good riddance... none shall repeat my mistakes); npc_text 8232'),
(343025, 2, 3430, 6, 2, 0, 'Lord Saltheril', 'Lord Saltheril throws parties at his country haven west of Fairbreeze Village to celebrate the magnificence of Quel''Thalas, and he means to keep throwing them whatever the Scourge may be doing to the south. He hounds Fairbreeze with requests for wine, appetizers and fireworks, cannot remember the faces of those who fetch them, and threatens to complain to the regent lord about the rudeness of the magistrix who must deal with him. His companion Elisara Sunstriker frets that too many undesirables are being let in, and wonders whether, with so many nobles crushed, her lord might soon be elevated.', 'quest 9067 description and request text; quest 9395 description and reward text; creature_text 16144, 16147; npc_text 8374'),
(343026, 2, 3430, 7, 2, 0, 'Larianna Riverwind', 'Larianna Riverwind keeps watch over the Scorched Grove from a lonely tower in southwestern Eversong, and her brother Ardeyn serves at Fairbreeze Village. Long ago she met the treant elder Old Whitebark beside the western runestone, and when his people helped hers rebuild their village she gave him a pendant marked with her initials. Now the grove has been burned to halt the Scourge''s taint, and the treants who try to regrow it must be cut down at her word. She calls it a somber task forced by desperate times, curses the Scourge for it, and insists the land must be protected whatever the cost.', 'quest 9258 description and reward text; quest 8473 description and reward text; quest 8474 description and reward text (initials L.R.); quest 10166 description; npc_text 8575'),
(343027, 2, 3430, 8, 0, 0, 'Chieftain Zul''Marosh', 'Chieftain Zul''Marosh rules the Amani of Zeb''Watha on the shore of Lake Elrendar, and the trolls of his lands raid elven territory almost daily. He is cruel even to other trolls. The Darkspear Ven''jashi, whose village Zul''Marosh burned, was captured after killing many Amani, poisoned and left in a cage at Tor''Watha to die. Ven''jashi laughs at death but has sworn to hold off the poison until he sees the chieftain''s head. Battle plans carried by Zul''Marosh mark the positions of the Farstrider Retreat and Fairbreeze Village, the first sign that the trolls intend more than raids.', 'quest 8479 description and reward text; quest 8476 description (daily raids); quest 9360 description and reward text; item 23249 Amani Invasion Plans drops from 15407; DB spawn: Zul''Marosh 15407'),
(343028, 2, 3430, 9, 0, 0, 'Thaelis the Hungerer', 'Thaelis the Hungerer is a notorious ringleader among the Wretched of the Ruins of Silvermoon, lurking in the Commons Hall. Silvermoon City has posted a reward for his head, charging him with repeated crimes against its people, among them the murder of two city guards. At Falconwing Square, where Sergeant Kan''ren has lost two of his men in a month, the bounty has at least one young ranger talking of hunting the beast down himself. Kan''ren hopes that with Thaelis gone, the Wretched will stay quiet for a while.', 'quest 8468 description and reward text; npc_text 8698 (Kan''ren); creature_text 16923 (Novice Ranger); warcraft.wiki.gg/wiki/Thaelis_the_Hungerer (Commons Hall); gameobject 180918 wanted poster'),
(343029, 3, 3430, 1, 2, 0, 'Reclaiming Sunstrider Isle', 'The young blood elves of Sunstrider Isle are put to work at once. Magistrix Erona sends them to thin the mana wyrms that have run wild around the Burning Crystals since the Sunwell fell, and then the lynxes those crystals have maddened, keeping their collars in hope of fashioning new restraints. Her assistant Lanthan Perilon has them put down the tenders that once kept the gardens, mourning them even as he asks, before sending them into Falthrien Academy against Felendren the Banished. Between those tasks, Well Watcher Solanian has them gather his scattered belongings and read the placard at Dath''Remar''s shrine, and Arcanist Helion teaches the hardest lesson: control the thirst for magic or become Wretched. At last the outrunners send them south through the ruins, where they find a slain courier and carry Erona''s package on to Falconwing Square.', 'quests 8325, 8326, 8327, 8334, 8335 (descriptions and reward texts); quests 8330, 8345, 8346; quests 8347, 9704, 9705, 8350'),
(343030, 3, 3430, 2, 2, 0, 'The Dwarven Spy', 'Trouble at the sanctums begins with small errands. Magister Jaronis of Falconwing Square sends a letter to Ley-Keeper Caidanis at the North Sanctum, who is busy entertaining a dwarven guest and passes the courier on to the West Sanctum. There Ley-Keeper Velania is furious: her warnings about overloading the sanctum went unheeded, a converter has been destroyed, and arcane wraiths are spilling out. Meanwhile Captain Aeldon Sunbrand, weary of rumors of Darnassian sabotage, sends help to search the sanctum for intruders. Night elf scouts are indeed found, and one carries maps, a sketch of a sanctum and notes in Dwarvish that call the elves'' experiments reckless. Sunbrand recognizes the hand of the Ironforge envoy, Prospector Anvilward, and orders him silenced quietly at the North Sanctum, lest word spread that Silvermoon let a spy into its lands.', 'quests 8472, 8895, 9119, 8486 (descriptions and reward texts); quests 8463, 9352, 8482, 8483 (descriptions and reward texts); creature_text 15405, 15420'),
(343031, 3, 3430, 3, 2, 0, 'The Fall of Sunsail Anchorage', 'Ranger Degolien was sent to Fairbreeze Village to look into a Wretched attack on a nearby shipyard, and found matters worse than feared: the Wretched hold the whole of Sunsail Anchorage. Until reinforcements arrive, he wants their thugs and hooligans taught some discipline. Velendris Whitemorn, whose rangers fled the yard without most of their weapons, sets about recovering the lost armaments while the Wretched are too sunk in their stupor to notice, then strikes at their leader, Aldaron the Reckless, on the top floor of the building by the anchorage. Under the rangers'' protection waits Captain Kelisendra, a merchant who ignored warnings to leave port. The Wretched took her magical goods, Grimscale murlocs carried off the rest of her cargo and her navigation rutters, and her crew abandoned ship.', 'quests 9256, 8892 (descriptions and reward texts); quests 8480, 9076; quests 8886, 8887 and npc_text 8227 (Kelisendra); quest_template_addon: 8892 PrevQuestID 9256 (Aeldon Sunbrand)'),
(343032, 3, 3430, 4, 2, 0, 'Duskwither''s Folly', 'At the Farstrider Retreat, Magister Duskwither frets over Apprentice Loralthalis, whom he sent back to his abandoned school to shut it down and who has not been heard from. She is found outside Duskwither Spire, safe but dismayed: magical creatures overrun the Spire, and its three power sources still burn. Once the power is cut, the truth comes out. Some of her fellow apprentices have fallen to their addiction, and the magister''s own journal, left behind in the Spire, records how his attempts to filter corrupted fel energies destroyed them. Returned to its author, the journal is condemned to the fire. Duskwither confesses he has blood on his hands, and takes small comfort that his former pupils no longer linger in a state where a blood elf is better off dead. Out on the grounds, the forgotten groundskeeper Wyllithen simply wants the beasts cleared away before his master returns.', 'quests 8888, 8889, 8890 (descriptions and reward texts); quest 8891 description and reward text; page_text 2846-2853; quests 9394, 8894; gameobject 181011 Magister Duskwither''s Journal spawned in the Spire'),
(343033, 3, 3430, 5, 2, 0, 'A Somber Task', 'At Fairbreeze Village, Ardeyn Riverwind explains how a foul taint runs ahead of the Scourge, and how the border runestones once held it back. When the westernmost stone fell, the elves burned the land around it, and he sends help to his sister Larianna at the Scorched Grove. Her request is a painful one. The treants, friends of the elves for years, are trying to regrow the burned forest, and since they cannot be persuaded to stop, they must be stopped by force. Among the fallen is Old Whitebark, and among his remains lies a pendant Larianna gave him when his people helped rebuild her village. She asks that it be buried by the grove''s runestone, where she first met him. There Whitebark''s spirit admits defeat: the land has changed forever, though perhaps one day a new tree will grow among the ashes.', 'quest 9258 description; quest 8473 description and reward text; quest 8474 reward text; quest 10166 description and reward text; item 23228 Old Whitebark''s Pendant drops from 15409; quest 10166 ends at Whitebark''s Spirit 19456'),
(343034, 3, 3430, 6, 2, 0, 'The Amani Threat', 'The blood elves hold little of their old lands, and Lieutenant Dawnrunner of the Farstrider Retreat means to defend every acre until her people can reach Outland. The Amani of Zeb''Watha and Tor''Watha raid daily, so she sends fighters to the villages southeast of the retreat to teach them a lesson. The smith Arathel Sunforge, admiring troll workmanship despite himself, wants the famed hammer of Spearcrafter Otembe. In a cage at Tor''Watha the dying Darkspear Ven''jashi begs for the head of Chieftain Zul''Marosh before the poison takes him; when it is brought, he gives up a gift hidden in the sand and goes to his rest. The chieftain''s battle plans, though, show the trolls preparing to strike Fairbreeze Village, and Dawnrunner rushes word to Ranger Degolien that the village must ready itself, with reinforcements to follow.', 'quest 8476 description; quest 8477 description and reward text; quest 8479 description and reward text; quest 9360 description and reward text; quest 9363 description and reward text');
